myList.splice(1, 0, 2);
console.log(myList);  // Output: [1, 2, 3, 4]

To add multiple elements to a list, you can use `concat()`:
let myList = [1, 2, 3];
myList = myList.concat([4, 5]);
console.log(myList);  // Output: [1, 2, 3, 4, 5]

You can access elements of an array using indices:
